#!/usr/bin/env python3
"""发布卫生闸门：区分项目残留与必须保留的第三方许可；命中即失败。"""
import argparse
import hashlib
import json
import re
import subprocess
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
BAD_PARTS = {'.git', '.workbuddy-ai', '.codex', '.agents', '.cursor', '__pycache__', 'node_modules'}
BAD_FILES = {'.DS_Store', '.env', '.credentials.json', 'runtime.json', 'shield.json', 'egress.json'}
PATTERNS = {
    'personal path': rb'/Users/(?!Shared/)[A-Za-z0-9_.-]+/',
    'agent environment': rb'(?i)generated by (?:codex|copilot)|co-authored-by\x3a',
    'credential': rb'sk-ant-[A-Za-z0-9_-]{24,}|gh[pousr]_[A-Za-z0-9]{32,}',
}
# 私人姓名摘要只从本机忽略的配置读取，不随公开源码发布。
PRIVATE_PROFILE = ROOT / 'build' / 'private-audit-markers.json'


def load_private_name_hashes():
    try:
        config = json.loads(PRIVATE_PROFILE.read_text(encoding='utf-8'))
    except FileNotFoundError:
        return set()
    except (OSError, ValueError):
        raise RuntimeError('本地隐私检查配置无法读取；停止检查，不输出配置内容') from None
    values = config.get('private_name_hashes') if isinstance(config, dict) else None
    if not isinstance(values, list) or not all(isinstance(v, str) and re.fullmatch(r'[0-9a-f]{64}', v) for v in values):
        raise RuntimeError('本地隐私检查配置格式错误；停止检查，不输出配置内容')
    return set(values)


PRIVATE_NAME_HASHES = load_private_name_hashes()
# 无关对标名称同样保存为摘要，避免检测规则本身携带这些名称。
DENIED_AGENT_TOKEN_HASHES = {'7bb366a5c146e062e8b0ef2fee5fc738d0ddcccc0f24aa30465adac4a05f2d7e'}
DENIED_TOKEN_HASHES = {
    'f94a3b7c975ad732194623909f5d3353c228e2bd66de6b228dc4b4781844741e',
    'dd740989f0e90b4040c92af5e554e41f0b539a2fe29543eb65f97c5140164ee8',
    '46ad36da6830c31058936db69ec5a9effb5858825df366cad0fb62bed233c802',
    '94a8508166b383be72181354eedf8cdc713c542cbcb8df45c0d2a292751d0f15',
}


def issues(name, data):
    p = Path(name)
    result = []
    if BAD_PARTS.intersection(p.parts) or p.name in BAD_FILES or p.suffix == '.pyc':
        result.append('private/generated file')
    # 只匹配已登记的私人姓名；其他上游版权人仍保留。许可文件同样检查隐私信息。
    decoded = data.decode('utf-8', errors='ignore')
    for run in re.findall(r'[\u3400-\u9fff]+', decoded):
        if any(hashlib.sha256(run[i:i+3].encode()).hexdigest() in PRIVATE_NAME_HASHES
               for i in range(len(run) - 2)):
            result.append('personal name')
            break
    token_hashes = {hashlib.sha256(token.lower()).hexdigest()
                    for token in re.findall(rb'[A-Za-z0-9_-]+', data)}
    if token_hashes & DENIED_TOKEN_HASHES:
        result.append('comparison attribution')
    if token_hashes & DENIED_AGENT_TOKEN_HASHES:
        result.append('agent environment')
    for label, pattern in PATTERNS.items():
        if re.search(pattern, data):
            result.append(label)
    return result


def source_files():
    for name in ('core', 'shield', 'web', 'tools', 'docs', '.github'):
        base = ROOT / name
        if not base.exists():
            continue
        for p in base.rglob('*'):
            rel = p.relative_to(ROOT)
            if (not p.is_file() or '__pycache__' in p.parts or 'cache' in p.parts
                    or p.suffix in ('.pyc', '.png', '.jpg', '.icns', '.zip')):
                continue
            yield rel.as_posix(), p.read_bytes()
    for p in ROOT.iterdir():
        if p.is_file() and p.suffix in ('.py', '.md', '.txt', '.sh', '.bat'):
            yield p.name, p.read_bytes()


def history_issues():
    failures = []
    objects = subprocess.check_output(['git', 'rev-list', '--objects', '--all'], cwd=ROOT, text=True)
    rows = [line.split(' ', 1) for line in objects.splitlines() if ' ' in line]
    if rows:
        # 一次 cat-file 读取历史对象，避免每个文件启动一个 Git 进程。
        proc = subprocess.run(['git', 'cat-file', '--batch'], cwd=ROOT,
                              input=''.join(obj + '\n' for obj, _ in rows).encode(),
                              capture_output=True, check=True)
        offset = 0
        for obj, name in rows:
            end = proc.stdout.index(b'\n', offset)
            header = proc.stdout[offset:end].split()
            size = int(header[2])
            data = proc.stdout[end + 1:end + 1 + size]
            offset = end + 2 + size
            if header[1] == b'blob':
                failures.extend(f'history {obj[:8]}/{name}: {reason}' for reason in issues(name, data))
    messages = subprocess.check_output(['git', 'log', '--all', '--format=%B'], cwd=ROOT)
    failures.extend(f'commit messages: {reason}' for reason in issues('commit-messages.txt', messages))
    return failures


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--source', action='store_true')
    ap.add_argument('--history', action='store_true')
    ap.add_argument('--history-content', action='store_true', help='核对可达历史文件与提交说明；发布新仓库前使用')
    ap.add_argument('archives', nargs='*')
    args = ap.parse_args()
    failures = []
    if args.source:
        for name, data in source_files():
            failures.extend(f'{name}: {reason}' for reason in issues(name, data))
        tracked = subprocess.run(['git', 'ls-files'], cwd=ROOT, capture_output=True, text=True, check=True)
        failures.extend(f'{n}: tracked agent metadata' for n in tracked.stdout.splitlines()
                        if BAD_PARTS.intersection(Path(n).parts))
    if args.history:
        rows = subprocess.check_output(['git', 'log', '--all', '--format=%an|%ae|%cn|%ce'], cwd=ROOT, text=True)
        if any(r != 'shlo|shlo@local|shlo|shlo@local' for r in rows.splitlines()):
            failures.append('Git history has non-project author/committer metadata')
    if args.history_content:
        failures.extend(history_issues())
    for filename in args.archives:
        with zipfile.ZipFile(filename) as z:
            if z.testzip():
                failures.append(f'{filename}: corrupt ZIP')
            names = z.namelist()
            if 'portable' in filename or any('.app/' in n for n in names):
                if not any(n.endswith('LICENSE.txt') for n in names):
                    failures.append(f'{filename}: missing runtime license')
            for name in names:
                if name.endswith('/'):
                    continue
                # 源码包有一个顶层目录，工具测试里的规则常量不是残留。
                logical = name.split('/', 1)[-1]
                failures.extend(f'{filename}/{name}: {reason}' for reason in issues(logical, z.read(name)))
    for failure in failures:
        print('FAIL:', failure)
    print(f'Release hygiene: {len(failures)} failures')
    return bool(failures)


if __name__ == '__main__':
    sys.exit(main())
